//! Whole-original judgment and lexical data extraction checks; source completion is separate.
use crate::lint::Registry;
#[path="../fixtures/original_policies/state_schema.rs"]mod original;
#[path="../fixtures/original_policies/state_schema_data.rs"]mod original_data;
#[path="../fixtures/native-state-schema/fixture.rs"]mod fixture;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
fn schema_record(schema:&crate::state_schema_data::Schema)->serde_json::Value{let mut decls:Vec<_>=schema.decls.iter().map(|(owner,vars)|(owner,vars.iter().map(|v|(&v.owner,&v.name,&v.mods,&v.vtype,v.is_list,&v.path,v.line)).collect::<Vec<_>>())).collect();decls.sort_by_key(|(owner,_)|*owner);let mut latent:Vec<_>=schema.latent.iter().collect();latent.sort();let mut codecs:Vec<_>=schema.codecs.iter().map(|(owner,keys)|{let mut keys:Vec<_>=keys.iter().collect();keys.sort();(owner,keys)}).collect();codecs.sort();serde_json::json!({"decls":decls,"latent":latent,"codecs":codecs,"registry":schema.registry,"safe":schema.safe_types()})}
#[test]fn unique_state_schema_judgment_preserves_entire_original_diagnostics_order_counts_and_reports(){for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("state-schema-original-{case}"));for(relative,text)in fixture::files(case).unwrap(){let file=root.join(relative);std::fs::create_dir_all(file.parent().unwrap()).unwrap();std::fs::write(file,text).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["state_schema".into()],raw:true,no_cache:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options.clone()).unwrap();let current=crate::run::Engine::new(crate::run::registry(),options).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let actual=current.run_one(current.reg.lints.iter().find(|lint|lint.meta().name=="state_schema").unwrap().as_ref());assert_eq!(record(&actual),record(&expected),"entire ordered state_schema report for {case}");assert!(!expected.run.notes.is_empty());assert!(expected.allow_used.is_empty());
 let files=old.tree.select(&crate::tree::CODE_DM);let frozen=original_data::Schema::build(&old.tree,&files);let data=crate::state_schema_data::Schema::build(&current.tree,&current.tree.select(&crate::tree::CODE_DM));let mut decls:Vec<_>=frozen.decls.iter().map(|(owner,vars)|(owner,vars.iter().map(|v|(&v.owner,&v.name,&v.mods,&v.vtype,v.is_list,&v.path,v.line)).collect::<Vec<_>>())).collect();decls.sort_by_key(|(owner,_)|*owner);let mut latent:Vec<_>=frozen.latent.iter().collect();latent.sort();let mut codecs:Vec<_>=frozen.codecs.iter().map(|(owner,keys)|{let mut keys:Vec<_>=keys.iter().collect();keys.sort();(owner,keys)}).collect();codecs.sort();assert_eq!(schema_record(&data),serde_json::json!({"decls":decls,"latent":latent,"codecs":codecs,"registry":frozen.registry,"safe":frozen.safe_types()}),"complete frozen lexical Schema data for {case}");}}

#[cfg(feature="native-policy")]
struct FinitePages<'a>{root:&'a std::path::Path,rows:Vec<(std::path::PathBuf,dm_preprocess::SourceText)>,budget:std::sync::Arc<crate::captured_generator_budget::Budget>}
#[cfg(feature="native-policy")]
impl crate::reactive_raw_policy_pages::RawPolicyPages for FinitePages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,crate::captured_raw_file::RawPolicyViews<'_>)->Result<bool,crate::captured_reactive_reads::Failure>)->Result<bool,crate::captured_reactive_reads::Failure>{for(path,text)in &self.rows{if !crate::captured_raw_file::with_original_policy_file(self.root,path,text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
#[cfg(feature="native-policy")]
#[test]fn native_state_schema_data_matches_whole_frozen_original_on_actual_fixture_bytes_without_claiming_source_completion(){
 use crate::captured_generator_budget::Budget;for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("state-schema-native-data-{case}"));let authored=fixture::files(case).unwrap();for(relative,text)in &authored{let file=root.join(relative);std::fs::create_dir_all(file.parent().unwrap()).unwrap();std::fs::write(file,text).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["state_schema".into()],raw:true,no_cache:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let root_budget=Budget::new(32*1024*1024).unwrap();let mut rows=Vec::new();let mut names:Vec<_>=authored.iter().map(|(relative,_)|*relative).collect();names.sort();for relative in names{let path=root.join(relative);let acquired=dm_preprocess::AcquiredSource::from_original_bytes(std::fs::read(&path).unwrap(),());rows.push((path,acquired.lease().source_text().clone()));}let pages=FinitePages{root:&root,rows,budget:root_budget.clone()};let actual=crate::captured_state_schema_pages::collect_from_pages(&pages,&root_budget,&||Ok(())).unwrap();assert_eq!(actual.sites(),expected.run.sites.as_slice(),"all original sites/order for {case}");assert_eq!(actual.notes(),expected.run.notes.as_slice(),"all original notes/counts for {case}");assert!(expected.allow_used.is_empty());
 let fresh=Budget::new(32*1024*1024).unwrap();let error=crate::captured_state_schema_pages::collect_from_pages(&pages,&fresh,&||Err(std::io::Error::from_raw_os_error(1450)));assert!(matches!(error,Err(crate::captured_reactive_reads::Failure::Operational(ref actual))if actual.raw_os_error()==Some(1450)));
 // These finite DATA callbacks deliberately do not construct the host-private
 // StateSchemaCompletion; the separate genuine workspace host test proves EOF.
 }}

#[path="../fixtures/original_policies/ownership_parents.rs"]mod original_parents;
#[test]fn borrowed_ownership_parent_walk_preserves_original_internal_and_trailing_slash_lookup(){for path in ["/obj/a","/mob/a","/turf/a","/area/a","/atom/movable/a","/datum/a","/client","/obj//a","/obj/","//obj","/","obj/a",""]{let mut actual=Vec::new();crate::raw_ownership_policy::visit_parents_using(path,&mut crate::key_policy_control::Compatibility,&mut|path,_|{actual.push(path.to_owned());Ok(())}).unwrap();assert_eq!(actual,original_parents::parents(path),"all exact original lookup paths for {path}");}}
